import fs from 'node:fs';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
const root=path.resolve('.tmp-d-index-cache-388c60c7adbe40a1b7fc0d6a71cf8e61/source');
const read=p=>fs.readFileSync(path.join(root,p),'utf8');
const write=(p,s)=>fs.writeFileSync(path.join(root,p),s);
const sha=s=>crypto.createHash('sha256').update(s).digest('hex');
const oldCatalog='2e8c5a26d09b69cd4007f86c99d25aa386bd00e7c0c54e422af59a711cade237';
const {computeMigrationCatalog}=await import(pathToFileURL(path.join(root,'scripts/system-backup-contract-check.mjs')));
const catalog=computeMigrationCatalog();assert.equal(catalog.file_count,96);assert.notEqual(catalog.hash,oldCatalog);
const mfa='backend/internal/systembackupevidence/testdata/download_mfa_probe_inputs.json';
const producer='backend/internal/systembackupevidence/testdata/download_producer_probe_inputs.json';
const oldMFA=read(mfa),oldProducer=read(producer),m=JSON.parse(oldMFA),p=JSON.parse(oldProducer);
