m.catalog_sha256=catalog.hash;m.migration_files=fs.readdirSync(path.join(root,'backend/internal/db/migrations')).filter(f=>f.endsWith('.sql')).sort();
const newMFA=JSON.stringify(m,null,2)+'\n';p.admission_inputs=newMFA;p.admission_sha256=sha(newMFA);const newProducer=JSON.stringify(p,null,2)+'\n';
write(mfa,newMFA);write(producer,newProducer);
const changes={};
const replace=(p,fn)=>{const before=read(p),after=fn(before);assert.notEqual(before,after,p);write(p,after);changes[p]=sha(after);};
replace('backend/internal/systembackupcontroller/bootstrap.go',s=>s.replaceAll(oldCatalog,catalog.hash).replace('ContractMigrationCatalogFileCount = 95','ContractMigrationCatalogFileCount = 96'));
replace('backend/internal/migrationcatalog/catalog_test.go',s=>s.replaceAll(oldCatalog,catalog.hash).replace('len(catalog.Filenames) != 95','len(catalog.Filenames) != 96'));
replace('backend/internal/systembackupevidence/sensitive_download_mfa_mysql_test.go',s=>s.replaceAll(oldCatalog,catalog.hash).replace('len(out.Files) != 95','len(out.Files) != 96'));
replace('backend/internal/systembackupevidence/download_producer_owner_mysql_test.go',s=>s.replaceAll(sha(oldMFA),sha(newMFA)).replaceAll(sha(oldProducer),sha(newProducer)));
replace('scripts/system-backup-d-download-producer-inputs.mjs',s=>s.replaceAll(sha(oldMFA),sha(newMFA)));
replace('scripts/system-backup-d-download-producer-dispatch.test.ps1',s=>s.replaceAll(sha(oldMFA),sha(newMFA)).replaceAll(sha(oldProducer),sha(newProducer)));
replace('scripts/system-backup-d-download-audit-bundle.mjs',s=>s.replace('catalog.file_count !== 95','catalog.file_count !== 96').replace('95-file catalog','96-file catalog'));
replace('backend/internal/systembackupevidence/download_gc_task_mysql_test.go',s=>s.replace('\tt.Log("PASS actual SQL GC task component cases=18','\tif t.Failed() { return }\n\tt.Log("PASS actual SQL GC task component cases=18'));
const report={kind:'d_prune_identity_isolated_input_refresh',old_catalog:oldCatalog,new_catalog:catalog,old_mfa_sha256:sha(oldMFA),mfa_sha256:sha(newMFA),old_producer_sha256:sha(oldProducer),producer_sha256:sha(newProducer),changes,sql_executed:false,dependencies_installed:false};
fs.writeFileSync('docs/evidence/d-prune-identity-input-refresh-20261021.json',JSON.stringify(report,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({catalog:catalog.hash,files:catalog.file_count,mfa:sha(newMFA),producer:sha(newProducer)}));
